<script setup>
import {ref,computed,onMounted} from 'vue'
import {request,upload} from './client'
import {previewMode} from '../preview/mode'
import PlatinumLock from './PlatinumLock.vue'
const props=defineProps({classroom:String,member:Object}),emit=defineEmits(['plans'])
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),page=ref(0),file=ref(null),formKey=ref(0),selected=ref(null)
const settings=ref({enabled:false,title:'Printed lesson pack',description:'',amount:'',bank_instructions:''})
const address=ref({recipient:'',phone:'',address_line1:'',address_line2:'',city:'',region:'',postal_code:'',country:'Sri Lanka',address_confirmed:false,reference:'',transfer_date:'',amount:''})
const review=ref({note:'',courier:'',tracking_reference:''})
const ordered=computed(()=>['Pending','Approved','Dispatched'].includes(data.value?.current_order_status))
const student=computed(()=>props.member.role==='Student'),money=n=>'LKR '+new Intl.NumberFormat('en-LK').format((n||0)/100)
async function run(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){data.value=await request('delivery','state',{classroom:props.classroom,page:page.value});if(data.value.offer){settings.value={...data.value.offer,enabled:!!data.value.offer.enabled,amount:data.value.offer.amount_minor/100};address.value.amount=data.value.offer.amount_minor/100}}
async function save(){await run(async()=>{await request('delivery','configure',{classroom:props.classroom,data:settings.value});await load();notice.value=settings.value.enabled?'Delivery is on for this class.':'Delivery is off. Existing orders remain available.'})}
async function submit(){await run(async()=>{if(!file.value)throw Error('Choose your bank slip');if(file.value.size>5*1024*1024)throw Error('Choose a slip no larger than 5 MB');if(!address.value.address_confirmed)throw Error('Confirm your residential address');const body=new FormData();body.append('file',file.value);const proof=previewMode?{name:file.value.name}:await upload('commercial','upload_proof',body);await request('delivery','submit_order',{classroom:props.classroom,data:{...address.value,offer_revision:data.value.offer.revision},proof:proof.name});file.value=null;formKey.value++;address.value.address_confirmed=false;page.value=0;await load();notice.value='Order submitted. Your teacher will check the bank payment before dispatch.'})}
async function decide(decision){await run(async()=>{await request('delivery','review_order',{name:selected.value.name,decision,note:review.value.note});selected.value=null;await load();notice.value='Payment review saved.'})}
async function dispatch(){await run(async()=>{await request('delivery','dispatch',{name:selected.value.name,...review.value});selected.value=null;await load();notice.value='Dispatch saved. The student can see the tracking details.'})}
function proof(row){if(previewMode){notice.value='Fictional preview slip. No bank payment was made.';return}window.open('/api/method/institute_lms.delivery.proof?'+new URLSearchParams({name:row.name}),'_blank','noopener')}
function choose(row){selected.value=row;review.value={note:'',courier:'',tracking_reference:''}}
onMounted(()=>run(load))
</script>
<template><section class="class-delivery"><header><div><h2>Tute & material delivery</h2><p>Printed learning, delivered to your door.</p></div><button class="button subtle small" :disabled="busy" @click="run(load)">Refresh</button></header><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" role="status">Loading…</p>
<template v-if="data"><PlatinumLock v-if="!data.available&&!student" :plan="data.plan" :institute="data.owner_type!=='Teacher'" @plans="emit('plans')"/><p v-else-if="!data.available" class="empty-mini">Material delivery is not available for this classroom.</p><template v-else>
<form v-if="!student" class="delivery-form" @submit.prevent="save"><label class="delivery-check"><input type="checkbox" v-model="settings.enabled"> Offer physical material delivery for this class</label><template v-if="settings.enabled"><label>Material / tute title<input v-model="settings.title" required maxlength="140"></label><label>What is included?<textarea v-model="settings.description" maxlength="1000"/></label><label>Total price including delivery · LKR<input v-model="settings.amount" type="number" min="0.01" step="0.01" required></label><label>Bank transfer instructions<textarea v-model="settings.bank_instructions" required maxlength="1000" placeholder="Account holder, bank, branch, account number and transfer instructions"/></label><p>{{data.owner_type==='Teacher'?'Payments belong to the independent teacher.':'Payments belong to the institute. Use the institute’s bank details.'}} Changing the title, description, price or bank details creates a new offer version. Existing orders keep their original details.</p></template><button class="button primary" :disabled="busy">Save delivery option</button></form>
<template v-if="student"><article v-if="data.offer?.enabled" class="delivery-offer"><span class="badge">Physical delivery</span><h3>{{data.offer.title}}</h3><p>{{data.offer.description}}</p><strong>{{money(data.offer.amount_minor)}} <small>including delivery · separate from class fees</small></strong><h4>Pay by bank transfer</h4><p class="bank-instructions">{{data.offer.bank_instructions}}</p><p class="field-help">Online payment is not connected yet. Upload a bank slip below for your teacher to review.</p></article><p v-else class="empty-mini">Your teacher has not enabled delivery for this class. Digital materials are in the Materials tab.</p>
<p v-if="ordered" role="status">You have already ordered this material · {{data.current_order_status}}. Your address and tracking details are in My deliveries below.</p><form v-if="data.offer?.enabled&&!ordered" :key="formKey" class="delivery-form" @submit.prevent="submit"><h3>Confirm your residential address</h3><p v-if="previewMode" class="field-help">Local preview: use fictional address and payment details.</p><p>Only you and the staff managing this class can see this delivery address. It does not appear on your public profile.</p><div class="delivery-fields"><label>Recipient name<input v-model="address.recipient" autocomplete="name" required maxlength="100"></label><label>Delivery phone<input v-model="address.phone" autocomplete="tel" type="tel" placeholder="+94771234567" required maxlength="16"></label><label>House / building and street<input v-model="address.address_line1" autocomplete="address-line1" required maxlength="200"></label><label>Address line 2 (optional)<input v-model="address.address_line2" autocomplete="address-line2" maxlength="200"></label><label>City / town<input v-model="address.city" autocomplete="address-level2" required maxlength="100"></label><label>District / province (optional)<input v-model="address.region" autocomplete="address-level1" maxlength="100"></label><label>Postal code<input v-model="address.postal_code" autocomplete="postal-code" required maxlength="100"></label><label>Country<input v-model="address.country" autocomplete="country-name" required maxlength="100"></label></div><label class="delivery-check"><input type="checkbox" v-model="address.address_confirmed" required> I confirm this residential address is correct for this delivery.</label><div class="delivery-fields"><label>Transferred amount · LKR<input type="number" v-model="address.amount" min="0.01" step="0.01" required></label><label>Transfer reference<input v-model="address.reference" required maxlength="140"></label><label>Transfer date<input type="date" v-model="address.transfer_date" required></label><label>Bank slip · PDF, PNG or JPEG · up to 5 MB<input type="file" accept="application/pdf,image/png,image/jpeg" required @change="file=$event.target.files[0]"></label></div><p>Uploading a slip does not confirm payment. Your teacher checks the received amount before approving delivery.</p><button class="button primary" :disabled="busy">Confirm address & submit slip</button></form></template>
<section class="delivery-orders"><h3>{{student?'My deliveries':'Delivery orders'}}</h3><p v-if="!data.orders.length">No delivery orders yet.</p><article v-for="row in data.orders" :key="row.name" class="delivery-order"><div class="delivery-order-heading"><h4>{{row.title}}</h4><span class="badge">{{row.status}}</span></div><p>{{row.recipient}} · {{money(row.amount_minor)}}</p><address>{{row.address_line1}}<template v-if="row.address_line2">, {{row.address_line2}}</template><br>{{row.city}}, {{row.region}} {{row.postal_code}} · {{row.country}}<br>{{row.phone}}</address><p class="field-help">Transfer {{row.reference}} · {{row.transfer_date}}</p><p v-if="row.review_note">{{row.review_note}}</p><p v-if="row.status==='Dispatched'"><strong>{{row.courier}}</strong> · Tracking: {{row.tracking_reference}}</p><button class="button subtle small" @click="proof(row)">View bank slip</button><button v-if="!student&&['Pending','Approved'].includes(row.status)" class="button primary small" @click="choose(row)">{{row.status==='Pending'?'Review payment':'Add dispatch details'}}</button><p v-if="student&&row.status==='Rejected'" class="field-help">Check the review note. Submit a new slip and confirm your address again to retry this order.</p></article><div class="inline"><button v-if="page>0" class="button subtle" :disabled="busy" @click="page--;run(load)">Newer orders</button><button v-if="data.has_more" class="button subtle" :disabled="busy" @click="page++;run(load)">Older orders</button></div></section>
<form v-if="selected" class="delivery-review" @submit.prevent="selected.status==='Approved'?dispatch():decide('Approved')"><h3>{{selected.status==='Pending'?'Review received payment':'Dispatch this order'}} · {{selected.recipient}}</h3><template v-if="selected.status==='Pending'"><p>Check {{money(selected.amount_minor)}} was received in the correct bank account before approving.</p><label>Verification / rejection note<textarea v-model="review.note" maxlength="1000" required/></label></template><template v-else><label>Courier<input v-model="review.courier" maxlength="140" required></label><label>Tracking reference<input v-model="review.tracking_reference" maxlength="140" required></label></template><div class="inline"><button class="button primary" :disabled="busy">{{selected.status==='Pending'?'Verify payment & approve':'Mark dispatched'}}</button><button v-if="selected.status==='Pending'" type="button" class="button subtle" :disabled="busy||!review.note.trim()" @click="decide('Rejected')">Reject payment</button><button type="button" class="text-button" @click="selected=null">Cancel</button></div></form>
</template></template></section></template>
<style scoped>.class-delivery header,.delivery-order-heading{display:flex;justify-content:space-between;align-items:center;gap:14px}.class-delivery header h2{margin:12px 0}.class-delivery p{line-height:1.7}.delivery-form,.delivery-offer,.delivery-review{border:1px solid #e5dfed;border-radius:12px;padding:22px;margin:20px 0}.delivery-form label,.delivery-review label{display:grid;gap:8px;margin:14px 0;font-size:13px}.delivery-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.class-delivery input:not([type=checkbox]),.class-delivery textarea{box-sizing:border-box;width:100%;min-width:0;font:inherit;padding:11px;border:1px solid #dad4e2;border-radius:8px;background:var(--surface,#fff);color:inherit}.class-delivery input[type=checkbox]{width:18px;height:18px;accent-color:#4d2186}.class-delivery .delivery-check{display:flex;align-items:center;gap:12px}.class-delivery .bank-instructions{white-space:pre-wrap}.delivery-offer strong{color:#4d2186;font-size:22px}.delivery-offer small{display:block;font-size:12px;font-weight:400}.delivery-order{border-bottom:1px solid #e5dfed;padding:18px 0}.delivery-order h4{margin:0}.delivery-order address{font-style:normal;line-height:1.7;overflow-wrap:anywhere}.delivery-order .button{margin:4px 8px 4px 0}.delivery-review{border-color:#bca5d8}.class-delivery .inline{flex-wrap:wrap}@media(max-width:600px){.delivery-fields{grid-template-columns:1fr}.delivery-form,.delivery-offer,.delivery-review{padding:16px}.class-delivery header{align-items:flex-start}.delivery-order-heading{flex-wrap:wrap}}</style>
